[{"order":1,"type":"heading","text":"Composite Pattern for Tree-Structured Hierarchies"},{"order":2,"type":"paragraph","text":"The Composite Design Pattern is a structural design pattern that lets you compose objects into tree structures to represent part-whole hierarchies. It allows clients to treat individual objects and compositions of objects uniformly."},{"order":3,"type":"subheading","text":"Core Concepts"},{"order":4,"type":"bullet_point","text":"Component: The base interface or abstract class for all objects in the hierarchy. It declares the interface for objecting with the composition."},{"order":5,"type":"bullet_point","text":"Leaf: Represents the end objects of a composition. A leaf can have no children and implements behavior for primitive tasks."},{"order":6,"type":"bullet_point","text":"Composite: Defines behavior for components having children. It stores child components and implements child-related operations in the Component interface."},{"order":7,"type":"subheading","text":"Implementation in Python"},{"order":8,"type":"code","text":"from abc import ABC, abstractmethod

class FileSystemComponent(ABC):
    @abstractmethod
    def show_details(self, indent=0):
        pass

class File(FileSystemComponent):
    def __init__(self, name):
        self.name = name

    def show_details(self, indent=0):
        print(" " * indent + f"- File: {self.name}")

class Directory(FileSystemComponent):
    def __init__(self, name):
        self.name = name
        self.children = []

    def add(self, component):
        self.children.append(component)

    def remove(self, component):
        self.children.remove(component)

    def show_details(self, indent=0):
        print(" " * indent + f"+ Directory: {self.name}")
        for child in self.children:
            child.show_details(indent + 4)"},{"order":9,"type":"subheading","text":"Usage Example"},{"order":10,"type":"code","text":"root = Directory("Root")
bin_dir = Directory("bin")
usr_dir = Directory("usr")

root.add(bin_dir)
root.add(usr_dir)

file1 = File("bash")
file2 = File("config.json")

bin_dir.add(file1)
usr_dir.add(file2)

root.show_details()"},{"order":11,"type":"subheading","text":"When to Use"},{"order":12,"type":"bullet_point","text":"When you want to represent part-whole hierarchies of objects."},{"order":13,"type":"bullet_point","text":"When you want clients to be able to ignore the difference between compositions of objects and individual objects."}]
